// ---------------------------------------------------------------------------
// BANNER ART — SVG decorative art layered BEHIND the typography of each team's
// banner. In production these would be AI-generated imagery or user uploads;
// here they're inline SVG compositions so everything stays self-contained.
// Each uses useId() so gradient/pattern IDs are unique even when the same
// team banner renders in multiple locations (standings + matchups + My Team).
// All art is drawn in a 280×36 viewBox; the outer <svg> scales uniformly.
// ---------------------------------------------------------------------------

// 1. SYNDICATE — Art Deco mob aesthetic: pinstripes + gold ornate frame
function SyndicateArt() {
  const id = useId();
  return (
    <>
      <defs>
        <radialGradient id={`${id}-vig`} cx="50%" cy="50%" r="75%">
          <stop offset="0%" stopColor="#000" stopOpacity="0" />
          <stop offset="100%" stopColor="#000" stopOpacity="0.5" />
        </radialGradient>
      </defs>
      {/* Diagonal pinstripes */}
      {[...Array(44)].map((_, i) => (
        <line key={i} x1={i * 9 - 50} y1="-5" x2={i * 9 + 10} y2="45"
              stroke="#e8c168" strokeWidth="0.22" opacity="0.09" />
      ))}
      <rect width="280" height="36" fill={`url(#${id}-vig)`} />
      {/* Double gold frame */}
      <rect x="2.5" y="2.5" width="275" height="31" fill="none" stroke="#e8c168" strokeWidth="0.5" opacity="0.5" />
      <rect x="4.5" y="4.5" width="271" height="27" fill="none" stroke="#e8c168" strokeWidth="0.25" opacity="0.35" />
      {/* Corner L-ornaments */}
      <g stroke="#e8c168" strokeWidth="0.7" fill="none" opacity="0.65">
        <path d="M 7 12 L 7 7 L 12 7" />
        <path d="M 273 12 L 273 7 L 268 7" />
        <path d="M 7 24 L 7 29 L 12 29" />
        <path d="M 273 24 L 273 29 L 268 29" />
      </g>
      {/* Fleur-de-lis emblem (center-left) */}
      <g transform="translate(22, 18)" fill="#e8c168" opacity="0.42">
        <path d="M 0 -7 C -2 -5 -3 -2 -2 0 L -3 0 C -5 0 -5 2 -3 3 L 3 3 C 5 2 5 0 3 0 L 2 0 C 3 -2 2 -5 0 -7 Z" />
        <rect x="-4" y="3" width="8" height="0.8" />
        <circle cx="0" cy="-4" r="0.8" />
      </g>
      {/* Mirror emblem (center-right) */}
      <g transform="translate(258, 18)" fill="#e8c168" opacity="0.42">
        <path d="M 0 -7 C -2 -5 -3 -2 -2 0 L -3 0 C -5 0 -5 2 -3 3 L 3 3 C 5 2 5 0 3 0 L 2 0 C 3 -2 2 -5 0 -7 Z" />
        <rect x="-4" y="3" width="8" height="0.8" />
        <circle cx="0" cy="-4" r="0.8" />
      </g>
    </>
  );
}

