// 3. AIRPLANE — 70s psychedelic: sunburst rays + groovy waves
function AirplaneArt() {
  const id = useId();
  return (
    <>
      <defs>
        <radialGradient id={`${id}-sun`} cx="5%" cy="50%" r="60%">
          <stop offset="0%" stopColor="#ffd700" stopOpacity="0.4" />
          <stop offset="60%" stopColor="#ff6b35" stopOpacity="0.2" />
          <stop offset="100%" stopColor="#ff6b35" stopOpacity="0" />
        </radialGradient>
      </defs>
      {/* Sunburst rays emanating from left */}
      <g opacity="0.22">
        {[...Array(11)].map((_, i) => {
          const angle = (i / 10) * 180 - 90;
          const rad = (angle * Math.PI) / 180;
          const x2 = 14 + Math.cos(rad) * 320;
          const y2 = 18 + Math.sin(rad) * 320;
          return (
            <line key={i} x1="14" y1="18" x2={x2} y2={y2}
                  stroke="#ffd700" strokeWidth={i % 2 === 0 ? "6" : "3"} />
          );
        })}
      </g>
      {/* Sun glow */}
      <circle cx="14" cy="18" r="60" fill={`url(#${id}-sun)`} />
      {/* Center sun */}
      <circle cx="14" cy="18" r="5" fill="#ffd700" opacity="0.6" />
      <circle cx="14" cy="18" r="2.5" fill="#fff" opacity="0.8" />
      {/* Groovy wave top */}
      <path d="M 60 2 Q 80 6 100 2 T 140 2 T 180 2 T 220 2 T 260 2 T 280 2"
            fill="none" stroke="#ffffff" strokeWidth="0.8" opacity="0.3" />
      {/* Groovy wave bottom */}
      <path d="M 60 34 Q 80 30 100 34 T 140 34 T 180 34 T 220 34 T 260 34 T 280 34"
            fill="none" stroke="#ffd700" strokeWidth="0.8" opacity="0.4" />
      {/* Airplane silhouette (tiny) */}
      <g transform="translate(250, 10) rotate(20)" fill="#ffffff" opacity="0.5">
        <polygon points="0,0 10,2 8,3 10,4 0,6 -1,3" />
      </g>
    </>
  );
}

