// ---------------------------------------------------------------------------
// LEAGUESAFE STRIP — full-width alert/status strip for dues collection.
// Adapts its visual treatment based on whether the current user has paid:
//   - Unpaid: warning-colored alert with prominent "Pay Now" action
//   - Paid:   neutral/branded strip reinforcing LeagueSafe integration
// The Pay Now button flips the state so you can see both views in the mockup.
// ---------------------------------------------------------------------------
function LeagueSafeStrip({ t, duesPaid, setDuesPaid, myTeam }) {
  // League economics
  const totalTeams = 12;
  const duesPerTeam = 500;
  const totalDues = totalTeams * duesPerTeam; // $6,000
  const teamsPaidWhenUnpaid = 9;
  const teamsPaidWhenPaid = 10;
  const teamsPaid = duesPaid ? teamsPaidWhenPaid : teamsPaidWhenUnpaid;
  const collected = teamsPaid * duesPerTeam;
  const pending = totalTeams - teamsPaid;
  const percent = (collected / totalDues) * 100;

  const warnBg = '#fef3ec';
  const warnBorder = '#e9a34b';
  const warnAccent = '#c46a1a';
  const warnDeep = '#7a3f0d';

  if (!duesPaid) {
    // -------- UNPAID / WARNING STATE --------
    // Compact horizontal layout: icon + message + button.
    // Progress bar lives in the status strip above, not duplicated here.
    return (
      <div style={{ background: warnBg, borderBottom: `1px solid ${warnBorder}` }}>
        <div className="max-w-[1400px] mx-auto px-6 py-3">
          <div className="flex items-center gap-4 flex-wrap">
            {/* Icon + message */}
            <div className="flex items-center gap-3 flex-1 min-w-0">
              <div className="w-10 h-10 rounded-full flex items-center justify-center shrink-0" style={{ background: warnAccent, color: '#fff' }}>
                <AlertCircle size={20} strokeWidth={2.2} />
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-[10px] font-bold uppercase tracking-[0.18em] mb-0.5" style={{ color: warnAccent }}>
                  Your league dues are unpaid
                </div>
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="fraunces font-bold text-[17px] leading-tight" style={{ color: warnDeep }}>
                    You owe ${duesPerTeam} for {myTeam.name}
                  </span>
                  <span className="text-[10px] px-1.5 py-0.5 rounded font-bold whitespace-nowrap" style={{ background: warnAccent, color: '#fff' }}>
                    37 DAYS OVERDUE
                  </span>
                </div>
                <div className="text-[11px] mt-0.5" style={{ color: warnDeep, opacity: 0.75 }}>
                  Due September 1 · Payments processed securely via LeagueSafe
                </div>
              </div>
            </div>

            {/* Pay button — inline with text */}
            <button
              onClick={() => setDuesPaid(true)}
              className="shrink-0 flex items-center gap-2 px-4 py-2.5 rounded-lg text-[13px] font-bold transition-all shadow-sm"
              style={{ background: warnAccent, color: '#fff' }}
              onMouseEnter={e => e.currentTarget.style.background = warnDeep}
              onMouseLeave={e => e.currentTarget.style.background = warnAccent}
            >
              <Shield size={14} strokeWidth={2.5} />
              Pay ${duesPerTeam} Now
              <ArrowUpRight size={14} strokeWidth={2.5} />
            </button>
          </div>
        </div>
      </div>
    );
  }

  // -------- PAID / NEUTRAL STATE --------
  return (
    <div style={{ background: t.primarySoft, borderBottom: `1px solid ${t.border}` }}>
      <div className="max-w-[1400px] mx-auto px-6 py-2.5">
        <div className="flex items-center gap-4 flex-wrap">
          {/* Brand + status */}
          <div className="flex items-center gap-2.5 shrink-0">
            <div className="w-7 h-7 rounded-md flex items-center justify-center" style={{ background: t.primary, color: t.accent }}>
              <Shield size={14} strokeWidth={2.2} />
            </div>
            <div>
              <div className="flex items-center gap-1.5">
                <span className="text-[11px] font-bold tracking-wider uppercase" style={{ color: t.primary }}>LeagueSafe</span>
                <span className="inline-flex items-center gap-0.5 text-[9px] font-bold px-1 py-0.5 rounded" style={{ background: t.success, color: '#fff' }}>
                  <CheckCircle2 size={8} strokeWidth={2.5} /> YOU PAID
                </span>
              </div>
              <div className="text-[11px]" style={{ color: t.textMuted }}>League dues collection status</div>
            </div>
          </div>

          {/* Progress bar */}
          <div className="flex-1 min-w-[240px]">
            <div className="flex items-center justify-between text-[11px] mb-1" style={{ color: t.primary }}>
              <span><b className="num">${collected.toLocaleString()}</b> / ${totalDues.toLocaleString()} collected</span>
              <span><b className="num">{teamsPaid}</b> of {totalTeams} teams paid · {pending} pending</span>
            </div>
            <div className="w-full h-2 rounded-full overflow-hidden" style={{ background: t.bgCard }}>
              <div
                className="h-full rounded-full transition-all duration-500"
                style={{ width: `${percent}%`, background: `linear-gradient(90deg, ${t.primary}, ${t.accent})` }}
              />
            </div>
          </div>

          {/* Details link */}
          <button
            onClick={() => setDuesPaid(false)}
            className="flex items-center gap-1 text-[12px] font-semibold shrink-0"
            style={{ color: t.primary }}
          >
            Payment details <ArrowUpRight size={13} />
          </button>
        </div>
      </div>
    </div>
  );
}
// ---------------------------------------------------------------------------
// TeamBanner — the commissioner/owner's custom team banner. In production
// these would be uploaded images or AI-generated from a prompt. Here they're
// CSS compositions to demonstrate the range of styles possible.
// ---------------------------------------------------------------------------
function TeamBanner({ team, size = 'md', className = '', style = {} }) {
  const heights = { sm: 28, row: 36, md: 44, lg: 56, xl: 72 };
  const fontSizes = { sm: 12, row: 14, md: 16, lg: 19, xl: 24 };
  const paddings = { sm: '0 10px', row: '0 14px', md: '0 16px', lg: '0 20px', xl: '0 24px' };
  const h = heights[size];
  const b = team.banner;
  const ArtComp = b.art ? BANNER_ART[b.art] : null;

  // PNG image banner — when a raster image is provided, render it as the entire
  // banner (text is already composited into the image). No gradient, no SVG
  // art layer, no text overlay.
  if (b.image) {
    return (
      <div className={`relative overflow-hidden rounded-md ${className}`}
           style={{ height: h, ...style }}>
        <img
          src={b.image}
          alt={team.name}
          style={{
            width: '100%',
            height: '100%',
            objectFit: 'cover',
            display: 'block',
          }}
        />
      </div>
    );
  }

  return (
    <div className={`relative overflow-hidden rounded-md flex items-center ${className}`}
         style={{
           background: b.bg,
           height: h,
           padding: paddings[size],
           ...style,
         }}>
      {/* Decorative SVG art layer — sits between the background and the text */}
      {ArtComp && (
        <svg
          className="absolute inset-0 pointer-events-none"
          width="100%"
          height="100%"
          viewBox="0 0 280 36"
          preserveAspectRatio="xMidYMid slice"
          style={{ display: 'block' }}
        >
          <ArtComp />
        </svg>
      )}
      <span
        className="relative truncate"
        style={{
          color: b.color,
          fontFamily: b.font === 'Fraunces' ? 'Fraunces, serif' : 'Archivo, sans-serif',
          fontWeight: b.weight,
          fontStyle: b.italic ? 'italic' : 'normal',
          fontSize: fontSizes[size],
          letterSpacing: `${b.tracking || 0}px`,
          textTransform: b.uppercase ? 'uppercase' : 'none',
          textShadow: b.shadow === 'none' ? 'none' : b.shadow,
          lineHeight: 1.1,
          zIndex: 1,
        }}
      >
        {team.name}
      </span>
    </div>
  );
}

// Small square team avatar/icon — used in chat, activity feed, tight spots
function TeamAvatar({ team, size = 32 }) {
  const a = team.avatar;
  return (
    <div
      className="rounded flex items-center justify-center shrink-0"
      style={{
        width: size, height: size,
        background: a.bg, color: a.color,
        fontFamily: a.font === 'Fraunces' ? 'Fraunces, serif' : 'Archivo, sans-serif',
        fontWeight: 800,
        fontSize: size * 0.38,
        letterSpacing: '-0.02em',
        lineHeight: 1,
      }}>
      {a.label}
    </div>
  );
}

function SectionHeader({ t, eyebrow, title, action }) {
  return (
    <div className="flex items-end justify-between gap-4 mb-3">
      <div>
        {eyebrow && <div className="text-[10px] font-bold uppercase tracking-[0.18em] mb-1" style={{ color: t.textMuted }}>{eyebrow}</div>}
        <h2 className="fraunces text-[22px] font-bold tracking-tight" style={{ color: t.text }}>{title}</h2>
      </div>
      {action}
    </div>
  );
}

function MatchupsSection({ t, matchups, teamById, showCustomHints }) {
  return (
    <section>
      <SectionHeader
        t={t}
        eyebrow="Week 7 · Sunday + Monday"
        title="This Week's Matchups"
        action={
          <button className="flex items-center gap-1 text-[12px] font-semibold" style={{ color: t.primary }}>
            All scores <ArrowUpRight size={13} />
          </button>
        }
      />
      <div className="lh-match-grid">
        {matchups.map(m => {
          const home = teamById[m.home];
          const away = teamById[m.away];
          const homeWin = m.homeScore > m.awayScore;
          const isLive = m.status === 'live';
          const isFinal = m.status === 'final';
          const myGame = home.isMe || away.isMe;

          return (
            <div
              key={m.id}
              className="rounded-xl overflow-hidden transition-all cursor-pointer"
              style={{
                background: t.bgCard,
                border: `1px solid ${myGame ? t.primary : t.border}`,
                boxShadow: myGame ? `0 0 0 2px ${t.primarySoft}` : 'none',
              }}
            >
              {/* Status header */}
              <div className="flex items-center justify-between px-3.5 py-2 text-[10px] font-bold uppercase tracking-wider"
                   style={{ background: t.bgSoft, borderBottom: `1px solid ${t.border}`, color: t.textMuted }}>
                <div className="flex items-center gap-1.5">
                  {isLive && <span className="w-1.5 h-1.5 rounded-full animate-pulse" style={{ background: t.danger }} />}
                  <span style={{ color: isLive ? t.danger : t.textMuted }}>
                    {isLive ? `● Live · ${m.quarter}` : `${m.quarter} · ${m.time}`}
                  </span>
                </div>
                {myGame && (
                  <span className="flex items-center gap-1 font-bold" style={{ color: t.primary }}>
                    <Shield size={10} strokeWidth={2.5} /> Your matchup
                  </span>
                )}
              </div>

              {/* Teams */}
              <div className="p-3 space-y-2">
                {[away, home].map((team, idx) => {
                  const isWinner = (idx === 0 && !homeWin) || (idx === 1 && homeWin);
                  const score = idx === 0 ? m.awayScore : m.homeScore;
                  const highlightBanner = showCustomHints && team.isMe;
                  return (
                    <div key={team.id} className="flex items-center gap-3">
                      <TeamBanner
                        team={team}
                        size="row"
                        style={{ width: 280 }}
                        className={`shrink-0 ${highlightBanner ? 'custom-hint' : ''}`}
                      />
                      <div className="flex-1" />
                      <div className="text-right shrink-0 min-w-[60px]">
                        <div className="num font-bold text-[20px] leading-none tracking-tight"
                             style={{ color: isFinal ? (isWinner ? t.text : t.textMuted) : t.text }}>
                          {score.toFixed(1)}
                        </div>
                        <div className="text-[10px] font-medium mt-0.5" style={{ color: t.textMuted }}>
                          {team.record}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
}
// Division header banner — mirrors the visual language of the hero banner
// ("The Legacy League" treatment) so the standings feel like they belong to
// the same league identity. Eyebrow with flanking rules, italic-gold
// emphasis on the distinguishing word, same forest-green + gold palette.
function DivisionBanner({ division, t, showCustomHints }) {
  return (
    <div
      className={`relative overflow-hidden rounded-md ${showCustomHints ? 'custom-hint' : ''}`}
      style={{
        background: division.bg,
        minHeight: 78,
        color: division.light,
      }}
    >
      {/* Painted end-zone turf — diagonal mowing stripes, the way
          groundskeepers actually cut and paint pro field turf. Alternating
          light/dark bands at ~30° give the banner that unmistakable
          stadium-grass texture without competing with the typography. */}
      <div className="absolute inset-0 pointer-events-none"
           style={{
             background: `repeating-linear-gradient(115deg, rgba(255,255,255,0.05) 0 22px, rgba(0,0,0,0.06) 22px 44px)`,
           }} />
      {/* Soft top-light / bottom-shadow — stadium lighting on turf */}
      <div className="absolute inset-0 pointer-events-none"
           style={{ background: 'linear-gradient(180deg, rgba(255,255,255,0.08) 0%, transparent 40%, transparent 70%, rgba(0,0,0,0.22) 100%)' }} />
      {/* Top + bottom gold hairlines */}
      <div className="absolute top-0 left-0 right-0 h-px" style={{ background: `linear-gradient(90deg, transparent, ${division.accent}, transparent)` }} />
      <div className="absolute bottom-0 left-0 right-0 h-px" style={{ background: `linear-gradient(90deg, transparent, ${division.accent}66, transparent)` }} />
      {/* Radial glow from bottom */}
      <div className="absolute inset-0 pointer-events-none"
           style={{ background: `radial-gradient(ellipse at 50% 130%, ${division.accent}22, transparent 60%)` }} />

      <div className="relative flex flex-col items-center justify-center py-3.5 px-5 text-center">
        {/* Eyebrow with flanking rules — division subtitle + meta separated by the division glyph */}
        <div className="flex items-center gap-2.5" style={{ color: division.accent }}>
          <div className="h-px w-7 md:w-10" style={{ background: 'currentColor', opacity: 0.5 }} />
          <span className="fraunces italic text-[10px] tracking-[0.24em] uppercase font-medium flex items-center gap-2" style={{ opacity: 0.9 }}>
            <span>{division.subtitle}</span>
            <span className="not-italic text-[8px]" style={{ opacity: 0.7 }}>{division.glyph}</span>
            <span>{division.meta}</span>
          </span>
          <div className="h-px w-7 md:w-10" style={{ background: 'currentColor', opacity: 0.5 }} />
        </div>

        {/* Wordmark — "The [Silverbacks]" with italic gold emphasis like the hero */}
        <h3 className="fraunces font-black leading-none tracking-[-0.01em] mt-2"
            style={{
              fontSize: 26,
              color: division.light,
              textShadow: '0 1px 14px rgba(0,0,0,0.3)',
            }}>
          The{' '}
          <span style={{ color: division.accent, fontStyle: 'italic', fontWeight: 700 }}>
            {division.italicPart}
          </span>
        </h3>
      </div>
    </div>
  );
}

function StandingsSection({ t, silverbacks, youngBulls, showCustomHints, compact = false }) {
  return (
    <section>
      <SectionHeader
        t={t}
        eyebrow={compact ? 'Through Week 6' : '12 Teams · 2 Divisions'}
        title="League Standings"
        action={
          <button className="flex items-center gap-1 text-[12px] font-semibold" style={{ color: t.primary }}>
            Full standings <ArrowUpRight size={13} />
          </button>
        }
      />
      <div className="rounded-xl overflow-hidden" style={{ background: t.bgCard, border: `1px solid ${t.border}` }}>
        <DivisionGroup t={t} division={divisions.silverbacks} teams={silverbacks} showCustomHints={showCustomHints} compact={compact} />
        <div style={{ height: 1, background: t.border }} />
        <DivisionGroup t={t} division={divisions['young-bulls']} teams={youngBulls} showCustomHints={showCustomHints} compact={compact} />
      </div>
    </section>
  );
}

function DivisionGroup({ t, division, teams, showCustomHints, compact = false }) {
  return (
    <div className="p-3">
      <DivisionBanner division={division} t={t} showCustomHints={showCustomHints} />
      {/* Column headers */}
      <div className="flex items-center gap-3 mt-3 px-2 pb-1.5 text-[10px] font-bold uppercase tracking-wider"
           style={{ color: t.textMuted, borderBottom: `1px solid ${t.border}` }}>
        <div style={{ width: 20 }} className="text-center shrink-0">#</div>
        <div style={{ width: compact ? 220 : 280 }} className="shrink-0">Team</div>
        {!compact && <div className="flex-1 min-w-0 hidden lg:block">Owner</div>}
        <div style={{ width: compact ? 52 : 56 }} className="text-center shrink-0">Rec</div>
        {!compact && <div style={{ width: 40 }} className="text-center shrink-0 hidden md:block">Div</div>}
        <div style={{ width: compact ? 56 : 60 }} className="text-right shrink-0">PF</div>
        {!compact && <div style={{ width: 52 }} className="text-right shrink-0 hidden md:block">PA</div>}
        <div style={{ width: compact ? 36 : 40 }} className="text-right shrink-0">Strk</div>
      </div>
      {/* Team rows */}
      <div className="pt-1">
        {teams.map((team, idx) => (
          <TeamRow key={team.id} t={t} team={team} rank={idx + 1} showCustomHints={showCustomHints && team.isMe} compact={compact} />
        ))}
      </div>
    </div>
  );
}

function TeamRow({ t, team, rank, showCustomHints, compact = false }) {
  const streakColor = team.streak.startsWith('W') ? t.success : t.danger;
  return (
    <div
      className="flex items-center gap-3 px-2 py-1 rounded-md transition-colors"
      style={{ background: team.isMe ? t.primarySoft : 'transparent' }}
      onMouseEnter={e => { if (!team.isMe) e.currentTarget.style.background = t.bgSoft; }}
      onMouseLeave={e => { if (!team.isMe) e.currentTarget.style.background = 'transparent'; }}
    >
      {/* Rank */}
      <div style={{ width: 20 }} className="flex items-center gap-0.5 justify-center shrink-0">
        <span className="fraunces font-bold text-[14px] num" style={{ color: rank <= 2 ? t.primary : t.textMuted }}>
          {rank}
        </span>
        {rank === 1 && <span style={{ color: t.accent, marginLeft: -2 }}><Crown size={10} fill="currentColor" /></span>}
      </div>
      {/* Team banner — 280×36 in full view, 220×28 in compact (same 7.78:1 aspect) */}
      <TeamBanner
        team={team}
        size={compact ? 'sm' : 'row'}
        style={{ width: compact ? 220 : 280 }}
        className={`shrink-0 ${showCustomHints ? 'custom-hint' : ''}`}
      />
      {/* Owner (hidden in compact) */}
      {!compact && (
        <div className="flex-1 min-w-0 hidden lg:block text-[12px] truncate" style={{ color: t.textMuted }}>
          {team.owner}
        </div>
      )}
      {/* Record */}
      <div style={{ width: compact ? 52 : 56, color: t.text }} className="text-center num text-[12px] font-semibold shrink-0">
        {team.record}
      </div>
      {/* Div record */}
      {!compact && (
        <div style={{ width: 40, color: t.textMuted }} className="text-center num text-[11px] shrink-0 hidden md:block">
          {team.divRec}
        </div>
      )}
      {/* PF */}
      <div style={{ width: compact ? 56 : 60, color: t.text }} className="text-right num text-[12px] font-semibold shrink-0">
        {team.pf.toFixed(1)}
      </div>
      {/* PA */}
      {!compact && (
        <div style={{ width: 52, color: t.textMuted }} className="text-right num text-[11px] shrink-0 hidden md:block">
          {team.pa.toFixed(1)}
        </div>
      )}
      {/* Streak */}
      <div style={{ width: compact ? 36 : 40, color: streakColor }} className="text-right num text-[11px] font-bold shrink-0">
        {team.streak}
      </div>
    </div>
  );
}
function ActivitySection({ t, activity, teamById }) {
  const iconFor = (type) => {
    if (type === 'trade') return { Icon: ArrowLeftRight, color: t.accent };
    if (type === 'waiver') return { Icon: DollarSign, color: t.primary };
    if (type === 'injury') return { Icon: Activity, color: t.danger };
    if (type === 'msg') return { Icon: MessageSquare, color: t.textMuted };
    return { Icon: CircleDot, color: t.textMuted };
  };

  return (
    <section>
      <SectionHeader
        t={t}
        eyebrow="Last 48 Hours"
        title="League Activity"
        action={
          <button className="flex items-center gap-1 text-[12px] font-semibold" style={{ color: t.primary }}>
            Full activity <ArrowUpRight size={13} />
          </button>
        }
      />
      <div className="rounded-xl overflow-hidden" style={{ background: t.bgCard, border: `1px solid ${t.border}` }}>
        {activity.map((item, idx) => {
          const { Icon, color } = iconFor(item.type);
          const actor = item.actor ? teamById[item.actor] : null;
          return (
            <div key={item.id} className="flex items-center gap-3 px-4 py-3"
                 style={{ borderBottom: idx < activity.length - 1 ? `1px solid ${t.border}` : 'none' }}>
              <div className="w-8 h-8 rounded-full flex items-center justify-center shrink-0"
                   style={{ background: `${color}18`, color }}>
                <Icon size={14} strokeWidth={2.2} />
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-[13px] leading-snug" style={{ color: t.text }}>{item.text}</div>
                <div className="text-[11px] mt-0.5" style={{ color: t.textMuted }}>{item.time}</div>
              </div>
              {actor && <TeamAvatar team={actor} size={28} />}
            </div>
          );
        })}
      </div>
    </section>
  );
}
// ---------------------------------------------------------------------------
// Position color tokens — fantasy-standard conventions so users recognize
// positions at a glance (Sleeper / ESPN use similar). Kept theme-independent
// because these are semantic, not decorative.
// ---------------------------------------------------------------------------
const POS_COLORS = {
  QB:   '#c9594a',
  RB:   '#2d8a56',
  WR:   '#3680c7',
  TE:   '#b8732a',
  FLEX: '#8957d1',
  SF:   '#5d6db8',
  K:    '#b38a14',
  DST:  '#5b6876',
  BN:   '#94a3b8',
};

// ---------------------------------------------------------------------------
// MY TEAM MODULE — left column of the League Home top section.
// Includes banner header, live matchup bar, full starting lineup with
// start/bench actions, and collapsible bench.
// ---------------------------------------------------------------------------
function MyTeamModule({ t, myTeam, roster, bench, showCustomHints }) {
  const [benchOpen, setBenchOpen] = useState(true);

  // Compute aggregate scores
  const liveOrFinalPts = roster.reduce((sum, r) => sum + (r.score ?? 0), 0);
  const pending = roster.filter(r => r.score == null).reduce((sum, r) => sum + r.proj, 0);
  const projectedTotal = liveOrFinalPts + pending;
  const oppTotal = 84.2; // static for mockup

  return (
    <section>
      <SectionHeader
        t={t}
        eyebrow="Week 7 · Dynasty SF PPR"
        title="My Team"
        action={
          <button className="flex items-center gap-1 text-[12px] font-semibold" style={{ color: t.primary }}>
            Full team page <ArrowUpRight size={13} />
          </button>
        }
      />

      <div className="rounded-xl overflow-hidden" style={{ background: t.bgCard, border: `1px solid ${t.border}` }}>
        {/* Header: banner + stat trio */}
        <div className="p-4 flex flex-col sm:flex-row items-stretch sm:items-center gap-4" style={{ borderBottom: `1px solid ${t.border}` }}>
          <TeamBanner
            team={myTeam}
            size="lg"
            style={{ width: '100%', maxWidth: 440 }}
            className={showCustomHints ? 'custom-hint' : ''}
          />
          <div className="flex-1 flex items-stretch justify-around gap-2">
            {[
              { label: 'Rec',  value: myTeam.record, sub: 'Rank #1' },
              { label: 'PF',   value: myTeam.pf.toFixed(1), sub: `Avg ${(myTeam.pf/7).toFixed(1)}` },
              { label: 'Strk', value: myTeam.streak, sub: '4 straight', highlight: true },
            ].map((s, i) => (
              <div key={i} className="flex-1 text-center">
                <div className="text-[9px] font-bold uppercase tracking-wider" style={{ color: t.textMuted }}>{s.label}</div>
                <div className="num font-bold text-[18px] leading-tight mt-0.5" style={{ color: s.highlight ? t.success : t.text }}>{s.value}</div>
                <div className="text-[10px] mt-0.5" style={{ color: t.textMuted }}>{s.sub}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Live matchup bar */}
        <div className="px-4 py-2.5 flex items-center justify-between gap-3 flex-wrap" style={{ background: t.primarySoft }}>
          <div className="flex items-center gap-2">
            <span className="w-1.5 h-1.5 rounded-full animate-pulse" style={{ background: t.danger }} />
            <span className="text-[11px] font-bold uppercase tracking-wider" style={{ color: t.primary }}>Week 7 · vs Hurts Locker</span>
          </div>
          <div className="flex items-center gap-3 text-[13px] num">
            <span className="font-bold" style={{ color: t.primary }}>Me {projectedTotal.toFixed(1)}</span>
            <span style={{ color: t.textMuted, opacity: .5 }}>·</span>
            <span style={{ color: t.textMuted }}>Opp {oppTotal.toFixed(1)}</span>
            <span className="text-[10px] font-bold px-1.5 py-0.5 rounded" style={{ background: t.success, color: '#fff' }}>+{(projectedTotal - oppTotal).toFixed(1)}</span>
          </div>
        </div>

        {/* STARTERS */}
        <div className="px-4 py-2 text-[10px] font-bold uppercase tracking-[0.18em] flex items-center justify-between"
             style={{ background: t.bgSoft, color: t.textMuted, borderBottom: `1px solid ${t.border}` }}>
          <span>Starters · {roster.length}</span>
          <span className="num">Proj {roster.reduce((s, r) => s + r.proj, 0).toFixed(1)}</span>
        </div>
        <div>
          {roster.map((r, i) => <RosterRow key={`s-${i}`} t={t} row={r} isStarter={true} />)}
        </div>

        {/* BENCH */}
        <button
          onClick={() => setBenchOpen(!benchOpen)}
          className="w-full px-4 py-2 text-[10px] font-bold uppercase tracking-[0.18em] flex items-center justify-between transition-colors"
          style={{ background: t.bgSoft, color: t.textMuted, borderTop: `1px solid ${t.border}`, borderBottom: benchOpen ? `1px solid ${t.border}` : 'none' }}
        >
          <span>Bench · {bench.length}</span>
          <span className="flex items-center gap-1">
            <span className="num">Proj {bench.reduce((s, r) => s + r.proj, 0).toFixed(1)}</span>
            <ChevronDown size={12} className={`transition-transform ${benchOpen ? 'rotate-180' : ''}`} />
          </span>
        </button>
        {benchOpen && (
          <div className="lh-bench-scroll">
            {bench.map((r, i) => <RosterRow key={`b-${i}`} t={t} row={r} isStarter={false} />)}
          </div>
        )}

        {/* Footer: lock time + save button */}
        <div className="p-3 flex items-center justify-between gap-3 flex-wrap" style={{ background: t.bgCard, borderTop: `1px solid ${t.border}` }}>
          <div className="text-[11px] flex items-center gap-1.5" style={{ color: t.textMuted }}>
            <Lock size={11} />
            Lineup locks <span style={{ color: t.text, fontWeight: 600 }}>Sun 1:00 PM</span>
          </div>
          <button className="px-3.5 py-1.5 rounded-md text-[12px] font-bold whitespace-nowrap transition-all"
                  style={{ background: t.primary, color: t.accent }}>
            Save Changes
          </button>
        </div>
      </div>
    </section>
  );
}

function RosterRow({ t, row, isStarter }) {
  const slotColor = POS_COLORS[row.slot] || POS_COLORS[row.pos] || t.textMuted;
  const posColor = POS_COLORS[row.pos] || t.textMuted;
  const isLive = row.status === 'live';
  const isFinal = row.status === 'final';
  const onBye = row.tag === 'BYE';

  const initials = row.player.split(' ').filter(Boolean).map(p => p[0]).slice(0, 2).join('');

  return (
    <div className="flex items-center gap-3 px-4 py-2 transition-colors"
         style={{ borderBottom: `1px solid ${t.border}` }}
         onMouseEnter={e => e.currentTarget.style.background = t.bgSoft}
         onMouseLeave={e => e.currentTarget.style.background = 'transparent'}>
      {/* Slot label pill */}
      <div className="w-11 shrink-0">
        <div className="text-[10px] font-bold uppercase tracking-wider text-center py-0.5 rounded"
             style={{ background: `${slotColor}1f`, color: slotColor }}>
          {row.slot}
        </div>
      </div>

      {/* Player avatar (initials in circle) */}
      <div className="w-8 h-8 rounded-full flex items-center justify-center shrink-0 text-[11px] font-bold"
           style={{ background: `${posColor}22`, color: posColor }}>
        {initials}
      </div>

      {/* Player info */}
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-1.5">
          <span className="text-[13px] font-semibold truncate" style={{ color: t.text }}>{row.player}</span>
          {onBye && <span className="text-[9px] font-bold px-1 py-0.5 rounded" style={{ background: `${t.danger}22`, color: t.danger }}>BYE</span>}
        </div>
        <div className="text-[11px] flex items-center gap-1" style={{ color: t.textMuted }}>
          <span className="font-semibold" style={{ color: posColor }}>{row.pos}</span>
          <span>·</span>
          <span>{row.team}</span>
          {!onBye && <><span>·</span><span>{row.opp}</span></>}
          {isLive && (
            <>
              <span>·</span>
              <span className="flex items-center gap-1 font-bold" style={{ color: t.danger }}>
                <span className="w-1 h-1 rounded-full animate-pulse" style={{ background: t.danger }} />
                {row.tag || 'LIVE'}
              </span>
            </>
          )}
        </div>
      </div>

      {/* Score / projection */}
      <div className="text-right shrink-0 min-w-[50px]">
        {row.score != null ? (
          <>
            <div className="num text-[15px] font-bold leading-none" style={{ color: isLive ? t.danger : t.text }}>
              {row.score.toFixed(1)}
            </div>
            <div className="text-[10px] mt-0.5" style={{ color: t.textMuted }}>
              {isLive ? 'live' : 'final'}
            </div>
          </>
        ) : (
          <>
            <div className="num text-[15px] font-bold leading-none" style={{ color: onBye ? t.textMuted : t.text, opacity: onBye ? 0.4 : 1 }}>
              {row.proj.toFixed(1)}
            </div>
            <div className="text-[10px] mt-0.5" style={{ color: t.textMuted }}>proj</div>
          </>
        )}
      </div>

      {/* Action button: Start / Bench */}
      <button
        className="text-[10px] font-bold uppercase tracking-wider px-2.5 py-1.5 rounded-md shrink-0 transition-all"
        style={{
          background: isStarter ? 'transparent' : t.primary,
          color: isStarter ? t.textMuted : t.accent,
          border: `1px solid ${isStarter ? t.border : t.primary}`,
          opacity: onBye && !isStarter ? 0.4 : 1,
        }}
        title={isStarter ? 'Move to bench' : 'Move to starting lineup'}
      >
        {isStarter ? 'Bench' : 'Start'}
      </button>
    </div>
  );
}

// ---------------------------------------------------------------------------
// FREE AGENTS — compact list of top available players this week
// ---------------------------------------------------------------------------
function FreeAgentsCard({ t, freeAgents }) {
  const trendIcon = (trend) => {
    if (trend === 'up')   return { Icon: TrendingUp, color: t.success, rotate: 0 };
    if (trend === 'down') return { Icon: TrendingUp, color: t.danger, rotate: 180 };
    return { Icon: CircleDot, color: t.textMuted, rotate: 0 };
  };

  return (
    <section>
      <SectionHeader
        t={t}
        eyebrow="Waiver Wire · Week 7"
        title="Top Free Agents"
        action={
          <button className="flex items-center gap-1 text-[12px] font-semibold" style={{ color: t.primary }}>
            All players <ArrowUpRight size={13} />
          </button>
        }
      />
      <div className="rounded-xl overflow-hidden" style={{ background: t.bgCard, border: `1px solid ${t.border}` }}>
        {freeAgents.map((p, i) => {
          const { Icon, color, rotate } = trendIcon(p.trend);
          const posColor = POS_COLORS[p.pos] || t.textMuted;
          const initials = p.player.split(' ').filter(Boolean).map(x => x[0]).slice(0, 2).join('');

          return (
            <div key={i} className="flex items-center gap-3 px-4 py-2.5"
                 style={{ borderBottom: i < freeAgents.length - 1 ? `1px solid ${t.border}` : 'none' }}>
              <div className="w-8 h-8 rounded-full flex items-center justify-center shrink-0 text-[11px] font-bold"
                   style={{ background: `${posColor}22`, color: posColor }}>
                {initials}
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-[13px] font-semibold truncate" style={{ color: t.text }}>{p.player}</div>
                <div className="text-[11px] flex items-center gap-1" style={{ color: t.textMuted }}>
                  <span className="font-semibold" style={{ color: posColor }}>{p.pos}</span>
                  <span>·</span>
                  <span>{p.team}</span>
                  <span>·</span>
                  <span className="num">{p.rostered}% rostered</span>
                  <Icon size={11} style={{ color, transform: `rotate(${rotate}deg)` }} />
                </div>
              </div>
              <div className="text-right shrink-0">
                <div className="num text-[13px] font-bold" style={{ color: t.text }}>{p.proj.toFixed(1)}</div>
                <div className="text-[10px]" style={{ color: t.textMuted }}>proj</div>
              </div>
              <button className="text-[10px] font-bold uppercase tracking-wider px-2.5 py-1.5 rounded-md shrink-0 transition-all"
                      style={{ background: t.primary, color: t.accent }}>
                Bid ${p.bid}
              </button>
            </div>
          );
        })}
      </div>
    </section>
  );
}

// ---------------------------------------------------------------------------
// LEAGUE CHAT — compact message thread with input
// ---------------------------------------------------------------------------
function LeagueChatCard({ t, chatMessages, teamById, myTeam }) {
  return (
    <section>
      <SectionHeader
        t={t}
        eyebrow="12 members · 3 online"
        title="League Chat"
        action={
          <button className="flex items-center gap-1 text-[12px] font-semibold" style={{ color: t.primary }}>
            Open chat <ArrowUpRight size={13} />
          </button>
        }
      />
      <div className="rounded-xl overflow-hidden flex flex-col" style={{ background: t.bgCard, border: `1px solid ${t.border}` }}>
        <div className="flex-1 overflow-hidden">
          {chatMessages.map((msg, i) => {
            const author = teamById[msg.author];
            if (!author) return null;
            return (
              <div key={msg.id} className="flex items-start gap-2.5 px-4 py-2.5"
                   style={{ borderBottom: i < chatMessages.length - 1 ? `1px solid ${t.border}` : 'none' }}>
                <TeamAvatar team={author} size={30} />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-1.5 mb-0.5 flex-wrap">
                    <span className="text-[11px] font-bold truncate" style={{ color: t.text }}>{author.name}</span>
                    {msg.commish && (
                      <span className="text-[8px] font-bold uppercase tracking-wider px-1 py-0.5 rounded flex items-center gap-0.5"
                            style={{ background: t.accent, color: t.primaryDark }}>
                        <Crown size={8} /> Commish
                      </span>
                    )}
                    <span className="text-[10px]" style={{ color: t.textMuted }}>{msg.time}</span>
                  </div>
                  <div className="text-[12px] leading-snug" style={{ color: t.text }}>{msg.text}</div>
                </div>
              </div>
            );
          })}
        </div>
        {/* Input */}
        <div className="p-2.5 flex items-center gap-2" style={{ borderTop: `1px solid ${t.border}`, background: t.bgSoft }}>
          <TeamAvatar team={myTeam} size={26} />
          <input
            type="text"
            placeholder="Send a message..."
            className="flex-1 text-[12px] bg-transparent outline-none px-2 py-1.5"
            style={{ color: t.text }}
          />
          <button className="w-8 h-8 rounded-md flex items-center justify-center transition-all"
                  style={{ background: t.primary, color: t.accent }}>
            <ArrowUpRight size={14} strokeWidth={2.5} />
          </button>
        </div>
      </div>
    </section>
  );
}

// ---------------------------------------------------------------------------
// TOP PERFORMERS — Tabbed by position, shows best-scoring players this week
// ---------------------------------------------------------------------------
function TopPerformersCard({ t, topPerformers }) {
  const positions = ['QB', 'RB', 'WR', 'TE', 'K', 'DST'];
  const [activePos, setActivePos] = useState('QB');
  const players = topPerformers[activePos] || [];

  return (
    <section>
      <SectionHeader
        t={t}
        eyebrow="Week 7 · in progress"
        title="Top Performers"
        action={
          <button className="flex items-center gap-1 text-[12px] font-semibold" style={{ color: t.primary }}>
            Full leaderboard <ArrowUpRight size={13} />
          </button>
        }
      />
      <div className="rounded-xl overflow-hidden" style={{ background: t.bgCard, border: `1px solid ${t.border}` }}>
        {/* Position tabs */}
        <div className="flex gap-1 p-1.5" style={{ borderBottom: `1px solid ${t.border}`, background: t.bgSoft }}>
          {positions.map(pos => {
            const active = activePos === pos;
            const color = POS_COLORS[pos];
            return (
              <button
                key={pos}
                onClick={() => setActivePos(pos)}
                className="flex-1 text-[11px] font-bold uppercase tracking-wider py-1.5 rounded transition-all"
                style={{
                  background: active ? `${color}22` : 'transparent',
                  color: active ? color : t.textMuted,
                  border: active ? `1px solid ${color}44` : '1px solid transparent',
                }}
                onMouseEnter={e => { if (!active) e.currentTarget.style.color = t.text; }}
                onMouseLeave={e => { if (!active) e.currentTarget.style.color = t.textMuted; }}
              >
                {pos}
              </button>
            );
          })}
        </div>
        {/* Player list */}
        <div>
          {players.map((p, i) => {
            const posColor = POS_COLORS[activePos] || t.textMuted;
            const initials = p.player.split(' ').filter(Boolean).map(x => x[0]).slice(0, 2).join('');
            const isLive = p.status === 'live';
            return (
              <div key={i} className="flex items-center gap-3 px-4 py-2.5"
                   style={{ borderBottom: i < players.length - 1 ? `1px solid ${t.border}` : 'none' }}>
                <div className="w-5 text-center shrink-0">
                  <span className="fraunces num font-bold text-[14px]" style={{ color: i === 0 ? t.primary : t.textMuted }}>
                    {i + 1}
                  </span>
                </div>
                <div className="w-8 h-8 rounded-full flex items-center justify-center shrink-0 text-[11px] font-bold"
                     style={{ background: `${posColor}22`, color: posColor }}>
                  {initials}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-[13px] font-semibold truncate" style={{ color: t.text }}>{p.player}</div>
                  <div className="text-[11px] flex items-center gap-1" style={{ color: t.textMuted }}>
                    <span className="font-semibold" style={{ color: posColor }}>{activePos}</span>
                    <span>·</span>
                    <span>{p.team}</span>
                    {isLive && (
                      <>
                        <span>·</span>
                        <span className="flex items-center gap-1 font-bold" style={{ color: t.danger }}>
                          <span className="w-1 h-1 rounded-full animate-pulse" style={{ background: t.danger }} />
                          LIVE
                        </span>
                      </>
                    )}
                  </div>
                </div>
                <div className="text-right shrink-0">
                  <div className="num text-[15px] font-bold leading-none" style={{ color: isLive ? t.danger : t.text }}>
                    {p.points.toFixed(1)}
                  </div>
                  <div className="text-[10px] mt-0.5" style={{ color: t.textMuted }}>pts</div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}

// ---------------------------------------------------------------------------
// LAST WEEK RECAP — Team of the Week 🏆 and Toilet Bowl 🚽
// ---------------------------------------------------------------------------
function LastWeekRecapCard({ t, lastWeekRecap, teamById }) {
  const best = teamById[lastWeekRecap.best.teamId];
  const worst = teamById[lastWeekRecap.worst.teamId];

  const Row = ({ emoji, label, labelColor, team, score, opponent, oppScore, verb }) => (
    <div className="flex items-start gap-3 p-4">
      <span className="text-[32px] leading-none shrink-0" style={{ marginTop: 2 }}>{emoji}</span>
      <div className="flex-1 min-w-0 space-y-2">
        <div className="text-[10px] font-bold uppercase tracking-[0.18em]" style={{ color: labelColor }}>
          {label}
        </div>
        <TeamBanner team={team} size="sm" style={{ width: '100%', maxWidth: 260 }} />
        <div className="text-[11px] flex items-center gap-1.5 flex-wrap" style={{ color: t.textMuted }}>
          <span className="num font-bold text-[13px]" style={{ color: t.text }}>{score.toFixed(1)}</span>
          <span>pts · {verb}</span>
          <span className="font-semibold" style={{ color: t.text }}>{opponent}</span>
          <span className="num">({oppScore.toFixed(1)})</span>
        </div>
      </div>
    </div>
  );

  return (
    <section>
      <SectionHeader
        t={t}
        eyebrow="Week 6 · Final"
        title="Last Week Recap"
      />
      <div className="rounded-xl overflow-hidden" style={{ background: t.bgCard, border: `1px solid ${t.border}` }}>
        <Row
          emoji="🏆"
          label="Team of the Week"
          labelColor={t.accentDark}
          team={best}
          score={lastWeekRecap.best.score}
          opponent={lastWeekRecap.best.opponent}
          oppScore={lastWeekRecap.best.oppScore}
          verb="def."
        />
        <div style={{ height: 1, background: t.border }} />
        <Row
          emoji="🚽"
          label="Toilet Bowl"
          labelColor={t.danger}
          team={worst}
          score={lastWeekRecap.worst.score}
          opponent={lastWeekRecap.worst.opponent}
          oppScore={lastWeekRecap.worst.oppScore}
          verb="lost to"
        />
      </div>
    </section>
  );
}

